150:   template <typename T>
151:   struct RationalT {
152:     T numerator;
153:     T denominator;
154:   };
155: 
156:   template <typename>
157:   struct is_rational : std::false_type {};
158: 
159:   template <typename U>
160:   struct is_rational<RationalT<U>> : std::true_type {};
161: 
162:   template <typename T>
163:   constexpr bool is_rational_v = is_rational<T>::value;
164: 
165:   using Rational = RationalT<uint32_t>;
166:   static_assert(sizeof(Rational) == 8, "Rational must be 8 bytes");
167: 
168:   using SRational = RationalT<int32_t>;
169:   static_assert(sizeof(SRational) == 8, "SRational must be 8 bytes");
170: 
171:   // TIFF data types
172:   // ===============
173:   // 1 = BYTE 8-bit unsigned integer.
174:   // 2 = ASCII 8-bit byte that contains a 7-bit ASCII code; the last byte
175:   //     must be NUL (binary zero).
176:   // 3 = SHORT 16-bit (2-byte) unsigned integer.
177:   // 4 = LONG 32-bit (4-byte) unsigned integer.
178:   // 5 = RATIONAL Two LONGs: the first represents the numerator of a
179:   //     fraction; the second, the denominator.
180:   // 6 = SBYTE An 8-bit signed (twos-complement) integer.
181:   // 7 = UNDEFINED An 8-bit byte that may contain anything, depending on
182:   //     the definition of the field.
183:   // 8 = SSHORT A 16-bit (2-byte) signed (twos-complement) integer.
184:   // 9 = SLONG A 32-bit (4-byte) signed (twos-complement) integer.
185:   // 10 = SRATIONAL Two SLONG’s: the first represents the numerator of a
186:   //      fraction, the second the denominator.
187:   // 11 = FLOAT Single precision (4-byte) IEEE format.
188:   // 12 = DOUBLE Double precision (8-byte) IEEE format
189:   enum class Type : uint16_t {
190:     BYTE = 1,
191:     ASCII = 2,
192:     SHORT = 3,
193:     LONG = 4,
194:     RATIONAL = 5,
195:     SBYTE = 6,
196:     UNDEFINED = 7,
197:     SSHORT = 8,
198:     SLONG = 9,
199:     SRATIONAL = 10,
200:     FLOAT = 11,
201:     DOUBLE = 12
202:   };
203: 
204:   template <Type type> struct TypeTraits;
205:   template <> struct TypeTraits<Type::BYTE> { using type = uint8_t; };
206:   template <> struct TypeTraits<Type::ASCII> { using type = char; };
207:   template <> struct TypeTraits<Type::SHORT> { using type = uint16_t; };
208:   template <> struct TypeTraits<Type::LONG> { using type = uint32_t; };
209:   template <> struct TypeTraits<Type::RATIONAL> { using type = Rational; };
210:   template <> struct TypeTraits<Type::SBYTE> { using type = int8_t; };
211:   template <> struct TypeTraits<Type::UNDEFINED> { using type = std::byte; };
212:   template <> struct TypeTraits<Type::SSHORT> { using type = int16_t; };
213:   template <> struct TypeTraits<Type::SLONG> { using type = int32_t; };
214:   template <> struct TypeTraits<Type::SRATIONAL> { using type = SRational; };
215:   template <> struct TypeTraits<Type::FLOAT> { using type = float; };
216:   template <> struct TypeTraits<Type::DOUBLE> { using type = double; };
217: 
218:   template <Type type> using TypeTraits_t = typename TypeTraits<type>::type;
219: 
220:   template <typename F>
221:   decltype(auto) dispatchType(Type type, F&& f) {
222:     switch (type) {
223:       case Type::BYTE:      return f.template operator()<Type::BYTE>();
224:       case Type::ASCII:     return f.template operator()<Type::ASCII>();
225:       case Type::SHORT:     return f.template operator()<Type::SHORT>();
226:       case Type::LONG:      return f.template operator()<Type::LONG>();
227:       case Type::RATIONAL:  return f.template operator()<Type::RATIONAL>();
228:       case Type::SBYTE:     return f.template operator()<Type::SBYTE>();
229:       case Type::UNDEFINED: return f.template operator()<Type::UNDEFINED>();
230:       case Type::SSHORT:    return f.template operator()<Type::SSHORT>();
231:       case Type::SLONG:     return f.template operator()<Type::SLONG>();
232:       case Type::SRATIONAL: return f.template operator()<Type::SRATIONAL>();
233:       case Type::FLOAT:     return f.template operator()<Type::FLOAT>();
234:       case Type::DOUBLE:    return f.template operator()<Type::DOUBLE>();
235:       default:
236:         throw std::runtime_error("Unknown TIFF entry type");
237:     }
238:   }
239: 
240:   inline uint32_t typeBytes(Type type) {
241:     return dispatchType(type, []<Type type>() -> uint32_t {
242:       return sizeof(TypeTraits_t<type>);
243:     });
244:   }
