470:     // IFD class
471:     // =========
472:     // An Image File Directory (IFD) consists of a 2-byte count of the
473:     // number of directory entries (i.e., the number of fields), followed
474:     // by a sequence of 12-byte field entries, followed by a 4-byte offset
475:     // of the next IFD (or 0 if none).
476:     class IFD {
477:     public:
478: 
479:       // Entry class
480:       // ===========
481:       // Each IFD entry is a 12-byte structure that describes a field in the
482:       // image. The structure is as follows:
483:       // - Bytes 0-1: The Tag that identifies the field.
484:       // - Bytes 2-3: The field Type.
485:       // - Bytes 4-7: The number of values (Count) of the indicated Type.
486:       // - Bytes 8-11: The Value is expected to begin on a word boundary; the
487:       //   corresponding Value Offset will thus be an even number. This file
488:       //   offset may point anywhere in the file, even after the image data.
489:       //   The value of the field, or an offset to the value if it is too large
490:       //   to fit in 4 bytes.
491:       //
492:       // Sort Order
493:       // ----------
494:       // The entries in an IFD must be sorted in ascending order by Tag.
495:       // The Values to which directory entries point need not be in any
496:       // particular order in the file.
497:       //
498:       // Value/Offset
499:       // ------------
500:       // To save time and space the Value Offset contains the Value instead of
501:       // pointing to the Value if and only if the Value fits into 4 bytes. If
502:       // the Value is shorter than 4 bytes, it is left-justified within the
503:       // 4-byte Value Offset, i.e., stored in the lower-numbered bytes. Whether
504:       // the Value fits within 4 bytes is determined by the Type and Count of
505:       // the field.
506:       //
507:       // Count
508:       // -----
509:       // Count (called Length in previous versions of the specification) is the
510:       // number of values. Note that Count is not the total number of bytes.
511:       // For example, a single 16-bit word (SHORT) has a Count of 1; not 2.
512:       // The value of the Count part of an ASCII field entry includes the NUL.
513:       // If padding is necessary, the Count does not include the pad byte.
514:       //
515:       // Types
516:       // -----
517:       // The field types and their sizes are defined in the `Type` enum.
518:       class Entry {
519:       public:
520:         Tag tag() const { return tag_; }
521:         Type type() const { return type_; }
522:         uint32_t count() const { return count_; }
523:         const std::byte* values() const { return values_.data(); }
524: 
525:         template <typename T>
526:         std::span<const T> values() const {
527:           if (sizeof(T) != TiffCraft::typeBytes(type_)) {
528:             throw std::runtime_error("Invalid type size for values span");
529:           }
530:           return std::span<const T>(reinterpret_cast<const T*>(values_.data()), count());
531:         }
532: 
533:         uint32_t bytes() const { return count() * TiffCraft::typeBytes(type_); }
534: 
535:         static Entry read(std::istream& stream, bool mustSwap = false) {
536:           Entry entry;
537:           entry.tag_ = static_cast<Tag>(readValue<uint16_t>(stream, mustSwap));
538:           entry.type_ = static_cast<Type>(readValue<uint16_t>(stream, mustSwap));
539:           entry.count_ = readValue<uint32_t>(stream, mustSwap);
540: 
541:           // Read the value
542:           const uint32_t valueSize = entry.bytes();
543:           entry.values_.resize(valueSize);
544:           if (valueSize <= sizeof(uint32_t)) {
545:             // Value fits in 4 bytes, read directly
546:             const uint32_t value = readValue<uint32_t>(stream);
547:             if (valueSize > 0) {
548:               std::memcpy(entry.values_.data(), &value, valueSize);
549:             }
550:           }
551:           else {
552:             // Value is too large, read as an offset
553:             uint32_t valueOffset = readValue<uint32_t>(stream, mustSwap);
554:             if (valueOffset < 8 || valueOffset % 2 != 0) {
555:               throw std::runtime_error("Invalid value offset in TIFF entry");
556:             }
557:             readAt(stream, valueOffset, entry.values_.data(), valueSize);
558:           }
559: 
560:           // Swap values after reading them to treat them as an array, instead
561:           // of a single `uint32_t`. This is because the values may not be a
562:           // single `uint32_t` but rather a sequence of smaller types (e.g.,
563:           // uint16_t, uint8_t).
564:           // This is necessary to ensure that the values are correctly
565:           // interpreted according to their type.
566:           if (mustSwap) {
567:             swapArray(entry.values_.data(), entry.type_, entry.count_);
568:           }
569: 
570:           if (entry.type_ == Type::ASCII) {
571:             // Ensure the last byte is NUL for ASCII type
572:             if (valueSize == 0) {
573:               throw std::runtime_error("ASCII entry must contain at least one byte");
574:             }
575:             if (entry.values_[valueSize - 1] != std::byte{0}) {
576:               throw std::runtime_error("ASCII value must end with NUL byte");
577:             }
578:           }
579: 
580:           return entry;
581:         }
582: 
583:         bool operator==(const Entry& other) const {
584:           return tag_ == other.tag_ &&
585:                  type_ == other.type_ &&
586:                  count_ == other.count_ &&
587:                  values_ == other.values_;
588:         }
589: 
590:       private:
591:         Tag tag_;                       // Tag identifying the field
592:         Type type_;                     // Type of the field
593:         uint32_t count_;                // Number of values
594:         std::vector<std::byte> values_; // Pointer to the value data
595:       };
596: 
597:       const std::map<Tag, Entry>& entries() const { return entries_; }
598: 
599:       const Entry& getEntry(Tag tag,
600:         std::string errorMessage = "Entry not found") const {
601:         auto it = entries_.find(tag);
602:         if (it == entries_.end()) {
603:           throw std::runtime_error(errorMessage);
604:         }
605:         return it->second;
606:       }
607: 
608:       static IFD read(std::istream& stream, bool mustSwap = false) {
609:         IFD ifd;
610: 
611:         // Read the number of entries
612:         uint16_t entryCount = readValue<uint16_t>(stream, mustSwap);
613: 
614:         // Read each entry
615:         Tag lastTag = Tag::Null;
616:         for (uint16_t i = 0; i < entryCount; ++i) {
617:           Entry entry = Entry::read(stream, mustSwap);
618:           ifd.entries_[entry.tag()] = std::move(entry);
619:           if (entry.tag() <= lastTag) {
620:             throw std::runtime_error("Entries must be sorted by tag in ascending order");
621:           }
622:           lastTag = entry.tag();
623:         }
624: 
625:         return ifd;
626:       }
627: 
628:       private:
629:         std::map<Tag, Entry> entries_; // Map of directory entries
630:     };
