752:   inline void load(std::istream& stream, LoadCallback&& callback, const LoadParams& params = {}) {
753:     // Read the TIFF image from the stream
754:     TiffImage image = TiffImage::read(stream);
755:     const auto& header = image.header();
756: 
757:     if (params.ifdIndex && params.ifdIndex.value() >= image.ifds().size()) {
758:       throw std::runtime_error("Requested IFD index is out of bounds");
759:     }
760: 
761:     for (size_t i = 0; i < image.ifds().size(); ++i) {
762:       if (!params.ifdIndex || params.ifdIndex.value() == i) {
763:         // If a specific IFD index is requested, only process that IFD
764:         // Otherwise, process all IFDs
765:         const auto& ifd = image.ifds()[i];
766:         if (ifd.entries().contains(Tag::StripOffsets)) {
767:           // image contains strip offsets
768:           callback(header, ifd, TiffImage::readImageStrips(stream, ifd));
769:         } else if (ifd.entries().contains(Tag::TileByteCounts)) {
770:           // image contains tile byte counts
771:           callback(header, ifd, TiffImage::readImageTiles(stream, ifd));
772:         } else {
773:           throw std::runtime_error("Unsupported IFD format");
774:         }
775:       }
776:     }
777:   }
