85: Image convertImageTo8Bits(Image image)
86: {
87:   Image image8;
88:   if (image.channels == 1)
89:   {
90:     image8 = Image::make<uint8_t, 1>(image.width, image.height);
91:   }
92:   else if (image.channels == 3)
93:   {
94:     image8 = Image::make<uint8_t, 3>(image.width, image.height);
95:   }
96:   else
97:   {
98:     throw std::runtime_error("Unsupported number of channels for conversion to 8 bits");
99:   }
100: 
101:   auto copyImage = [&]<typename SrcType>() {
102: 
103:     auto* src = image.dataPtr<SrcType>();
104:     const auto srcRowStride = image.rowStride / sizeof(SrcType);
105:     const auto srcColStride = image.colStride / sizeof(SrcType);
106:     const auto srcChanStride = image.chanStride / sizeof(SrcType);
107:     const auto srcShift = sizeof(SrcType) * 8 - 8;
108: 
109:     auto* dst = image8.dataPtr<uint8_t>();
110: 
111:     for (int h = 0; h < image.height; ++h) {
112:       const auto* srcRow = src + h * srcRowStride;
113:       auto* dstRow = dst + h * image8.rowStride;
114:       for (int w = 0; w < image.width; ++w) {
115:         const auto* srcPixel = srcRow + w * srcColStride;
116:         auto* dstPixel = dstRow + w * image8.colStride;
117:         for (int c = 0; c < image.channels; ++c) {
118:           const auto* srcChan = srcPixel + c * srcChanStride;
119:           auto* dstChan = dstPixel + c * image8.chanStride;
120:           *dstChan = static_cast<uint8_t>(*srcChan >> srcShift);
121:         }
122:       }
123:     }
124:   };
125: 
126:   if (image.bitDepth == 16) {
127:     copyImage.template operator()<uint16_t>();
128:   }
129:   else if (image.bitDepth == 32) {
130:     copyImage.template operator()<uint32_t>();
131:   }
132:   else if (image.bitDepth == 8) {
133:     copyImage.template operator()<uint8_t>();
134:   }
135:   else {
136:     throw std::runtime_error("Unsupported bit depth for conversion to 8 bits");
137:   }
138: 
139:   return image8;
140: }
