145:   if (filename.substr(filename.find_last_of(".") + 1) != "png") {
146:     throw std::runtime_error("Only PNG format is supported for saving images");
147:   }
148: 
149:   // Single channel 8-bit non-float image
150:   if (image.channels == 1 && image.bitDepth == 8) {
151:     if (image.colStride != 1 || image.chanStride != 1) {
152:       throw std::runtime_error("Invalid strides for single channel 8-bit image");
153:     }
154:     if (!stbi_write_png(filename.c_str(), image.width, image.height, image.channels,
155:           reinterpret_cast<const uint8_t*>(image.data.data()), image.rowStride)) {
156:       throw std::runtime_error("Failed to save PNG image");
157:     }
158:     return; // Success
159:   }
160: 
161:   // 3-channel 8-bit RGB image
162:   if (image.channels == 3 && image.bitDepth == 8) {
163:     if (image.colStride != 3 || image.chanStride != 1) {
164:       throw std::runtime_error("Invalid strides for 3-channel 8-bit RGB image");
165:     }
166:     if (!stbi_write_png(filename.c_str(), image.width, image.height, image.channels,
167:           reinterpret_cast<const uint8_t*>(image.data.data()), image.rowStride)) {
168:       throw std::runtime_error("Failed to save PNG image");
